/**
 * Megh branding for the Swagger UI page (`useOpenApi`): the top-bar logo
 * and the favicon. Generated from docs/content/public/megh-logo.svg and
 * favicon.ico; embedded so they ship in dist/ and survive bundling.
 */

/** The Megh logo (SVG, base64). */
export const MEGH_LOGO_SVG_BASE64 =
  "";

/** The Megh favicon (ICO, base64). */
export const MEGH_FAVICON_ICO_BASE64 =
  "";

/**
 * The `logo` and `theme` options for `@fastify/swagger-ui`: the Megh logo and
 * favicon unless the app passes its own. `logo: null` shows Swagger UI's
 * built-in logo instead; `theme` is merged over the Megh favicon.
 */
export function swaggerUiBranding(
  options: { logo?: unknown; theme?: Record<string, unknown> } = {},
) {
  return {
    logo:
      options.logo === undefined
        ? {
            type: "image/svg+xml",
            content: Buffer.from(MEGH_LOGO_SVG_BASE64, "base64"),
          }
        : options.logo,
    theme: {
      favicon: [
        {
          filename: "favicon.ico",
          rel: "icon",
          sizes: "16x16 24x24 32x32 48x48 64x64",
          type: "image/x-icon",
          content: Buffer.from(MEGH_FAVICON_ICO_BASE64, "base64"),
        },
      ],
      ...options.theme,
    },
  };
}
